import{_ as t,c as a,o,ag as c}from"./chunks/framework.Bw-5EFTY.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/rules/pattern.md","filePath":"en/docs/rules/pattern.md"}'),d={name:"en/docs/rules/pattern.md"};function s(r,e,n,l,i,p){return o(),a("div",null,e[0]||(e[0]=[c(`<h2 id="pattern" tabindex="-1">pattern <a class="header-anchor" href="#pattern" aria-label="Permalink to &quot;pattern&quot;">​</a></h2><p><code>pattern</code> is the expression used in Whistle rules to match request URLs. It supports multiple matching methods, including URL fragment/domain, wildcards, and regular expressions.</p><h2 id="request-url-types" tabindex="-1">Request URL Types <a class="header-anchor" href="#request-url-types" aria-label="Permalink to &quot;Request URL Types&quot;">​</a></h2><p>Whistle supports three types of request URLs:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Format</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Tunnel proxy</strong></td><td style="text-align:left;"><code>tunnel://domain:port</code></td><td style="text-align:left;"><code>tunnel://www.test.com:443</code></td></tr><tr><td style="text-align:left;"><strong>WebSocket</strong></td><td style="text-align:left;"><code>ws[s]://domain[:port]/[path/to[?query]]</code></td><td style="text-align:left;"><code>wss://www.test.com/path?a=1&amp;b=2</code><br><code>ws://www.example.com:8080/path</code></td></tr><tr><td style="text-align:left;"><strong>HTTP/HTTPS</strong></td><td style="text-align:left;"><code>http[s]://domain[:port]/[path/to][?query]</code></td><td style="text-align:left;"><code>https://www.test.com/path</code><br><code>http://www.example.com/path?a=1&amp;b=2</code></td></tr></tbody></table><blockquote><p>The hash part of a URL (i.e., <code>#</code> and everything after it) is not sent to the server. Hashes only work on the client side (e.g., browsers) and cannot be directly obtained by the server.</p></blockquote><h2 id="url" tabindex="-1">URL Fragment <a class="header-anchor" href="#url" aria-label="Permalink to &quot;URL Fragment {#url}&quot;">​</a></h2><p>The URL fragment is used to match request URLs with flexible patterns. The matching rules are categorized as follows.</p><h3 id="_1-domain-matching" tabindex="-1">1. Domain Matching <a class="header-anchor" href="#_1-domain-matching" aria-label="Permalink to &quot;1. Domain Matching&quot;">​</a></h3><ul><li><p><strong>Plain domain</strong>: <code>example.com</code><br> Matches all requests under this domain, regardless of port and protocol (http/https).<br> ✅ <code>https://example.com/path/to?query</code><br> ✅ <code>https://example.com:9090/path/to?query</code></p></li><li><p><strong>Domain with port</strong>: <code>example.com:8080</code><br> Matches only requests for the specified port (8080).<br> ✅ <code>https://example.com:8080/path/to?query</code><br> ❌ <code>https://example.com:9090/path/to?query</code> ❌ <code>https://example.com/path/to?query</code></p></li></ul><h3 id="_2-protocol-matching" tabindex="-1">2. Protocol Matching <a class="header-anchor" href="#_2-protocol-matching" aria-label="Permalink to &quot;2. Protocol Matching&quot;">​</a></h3><ul><li><p><strong>With protocol</strong>: <code>https://example.com/path/to</code><br> Matches only requests using the same protocol.</p></li><li><p><strong>Without protocol</strong>: <code>example.com/path/to</code> or <code>//example.com/path/to</code><br> Matches any protocol (http, https, etc.). Path matching follows the same rules as with protocol (see below).</p></li></ul><h3 id="_3-path-query-parameter-matching" tabindex="-1">3. Path &amp; Query Parameter Matching <a class="header-anchor" href="#_3-path-query-parameter-matching" aria-label="Permalink to &quot;3. Path &amp; Query Parameter Matching&quot;">​</a></h3><h4 id="_3-1-without-query-parameters" tabindex="-1">3.1 Without Query Parameters <a class="header-anchor" href="#_3-1-without-query-parameters" aria-label="Permalink to &quot;3.1 Without Query Parameters&quot;">​</a></h4><p>Pattern: <code>https://example.com/path/to</code><br> Rule: <strong>Path prefix matching</strong> (using <code>/</code> as boundary).</p><ul><li>✅ <code>https://example.com/path/to</code></li><li>✅ <code>https://example.com/path/to/xxx?query</code></li><li>❌ <code>https://example.com/path/toxxx</code> (missing <code>/</code> boundary after <code>to</code>)</li></ul><h4 id="_3-2-with-query-parameters" tabindex="-1">3.2 With Query Parameters <a class="header-anchor" href="#_3-2-with-query-parameters" aria-label="Permalink to &quot;3.2 With Query Parameters&quot;">​</a></h4><p>Pattern: <code>https://example.com/path/to?xxx</code><br> Rule: <strong>Exact path</strong> and query string <strong>prefix</strong> matching.</p><ul><li>✅ <code>https://example.com/path/to?xxx</code></li><li>✅ <code>https://example.com/path/to?xxxyyy&amp;zzzzz</code></li><li>❌ <code>https://example.com/path/to/yyy?xxx</code> (path differs)</li></ul><h3 id="_4-exact-matching" tabindex="-1">4. Exact Matching <a class="header-anchor" href="#_4-exact-matching" aria-label="Permalink to &quot;4. Exact Matching&quot;">​</a></h3><p>Use the <code>$</code> prefix for stricter matching.</p><ul><li><p><code>$https://example.com/path/to</code><br> Matches <strong>exact path</strong> (with <code>/</code> boundary), any query parameters.<br> ✅ <code>https://example.com/path/to</code><br> ✅ <code>https://example.com/path/to?query</code><br> ❌ <code>https://example.com/path/to/xxx</code></p></li><li><p><code>$https://example.com/path/to?query</code><br> Matches <strong>exact path and exact query string</strong>.<br> ✅ <code>https://example.com/path/to?query</code><br> ❌ <code>https://example.com/path/to?query=1</code><br> ❌ <code>https://example.com/path/to</code></p></li><li><p>Exact match without protocol: <code>$example.com/path/to</code> (same behavior, any protocol)</p></li></ul><h3 id="domain-wildcard" tabindex="-1">5. Domain Wildcard <a class="header-anchor" href="#domain-wildcard" aria-label="Permalink to &quot;5. Domain Wildcard {#domain-wildcard}&quot;">​</a></h3><p>Use <code>*</code> or <code>**</code> in the <code>domain:port</code> part for fuzzy matching.</p><ul><li><p><code>*</code> : Matches zero or more non-<code>.</code> characters (equivalent to regex <code>/[^/?.]*/</code>).<br> Example: <code>https://*.example.com/path/to</code><br> ✅ <code>https://www.example.com/path/to</code><br> ✅ <code>https://abc.example.com/path/to/xxx?query</code> ❌ <code>https://a.b.example.com/path/to</code></p></li><li><p><code>**</code> : Matches zero or more arbitrary characters except <code>/</code> and <code>?</code> (equivalent to regex <code>/[^/?]*/</code>).<br> Example: <code>https://**.example.com:8*/path/to</code><br> ✅ <code>https://foo-bar.example.com:8080/path/to</code> ✅ <code>https://a.b.example.com:8888/path/to</code></p></li><li><p><code>***</code> and more: not recommended.</p></li></ul><blockquote><p>Note: <code>*</code> is also a legal character in URL paths. If you need to use wildcards in the path part, see <a href="#wildcard">Wildcard Matching</a>.</p></blockquote><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pattern</th><th>Protocol</th><th>Port</th><th>Path Matching</th><th>Query Matching</th></tr></thead><tbody><tr><td><code>example.com</code></td><td>Any</td><td>Any</td><td>-</td><td>-</td></tr><tr><td><code>example.com:8080</code></td><td>Any</td><td>8080</td><td>-</td><td>-</td></tr><tr><td><code>https://example.com/path/to</code></td><td>https</td><td>Any</td><td>Prefix (<code>/</code> boundary)</td><td>Any</td></tr><tr><td><code>https://example.com/path/to?xxx</code></td><td>https</td><td>Any</td><td>Exact</td><td>Prefix</td></tr><tr><td><code>$https://example.com/path/to</code></td><td>https</td><td>Any</td><td>Exact</td><td>Any</td></tr><tr><td><code>$https://example.com/path/to?xxx</code></td><td>https</td><td>Any</td><td>Exact</td><td>Exact</td></tr><tr><td><code>example.com/path/to</code> <br> or <code>//example.com/path/to</code></td><td>Any</td><td>Any</td><td>Prefix (<code>/</code> boundary)</td><td>Any</td></tr></tbody></table><h2 id="wildcard" tabindex="-1">Wildcard Matching <a class="header-anchor" href="#wildcard" aria-label="Permalink to &quot;Wildcard Matching {#wildcard}&quot;">​</a></h2><p>In <a href="#url">URL Fragment Matching</a>, because <code>*</code> is a legal character in URL paths, wildcards cannot be used directly in the path or query part.<br> If you need to use wildcards in the <strong>path</strong> or <strong>query parameters</strong>, prefix the URL with <code>^</code>. Then <code>*</code>, <code>**</code>, <code>***</code> are interpreted as wildcards.</p><h3 id="_1-domain-wildcard" tabindex="-1">1. Domain Wildcard <a class="header-anchor" href="#_1-domain-wildcard" aria-label="Permalink to &quot;1. Domain Wildcard&quot;">​</a></h3><p>The syntax is exactly the same as the <a href="#domain-wildcard">Domain Wildcard in URL Fragment</a>:</p><ul><li><code>*</code>: Matches zero or more non-<code>.</code> characters (regex <code>/[^/?.]*/</code>)</li><li><code>**</code>: Matches zero or more arbitrary characters except <code>/</code> and <code>?</code> (regex <code>/[^/?]*/</code>)</li></ul><p><strong>Example</strong>: <code>^wss://*.example.com/path/to</code></p><p>✅ Matches:</p><ul><li><code>wss://a.example.com/path/to</code></li><li><code>wss://b.example.com/path/to/xxx?query</code></li></ul><p>❌ Does not match:</p><ul><li><code>wss://a.example.com/path/toxxx</code> (missing <code>/</code> boundary)</li><li><code>wss://a.b.example.com/path/to</code> (<code>*</code> does not match dot)</li></ul><h3 id="_2-path-wildcard" tabindex="-1">2. Path Wildcard <a class="header-anchor" href="#_2-path-wildcard" aria-label="Permalink to &quot;2. Path Wildcard&quot;">​</a></h3><p>Applies to the <strong>path part</strong> of the URL (after domain, before <code>?</code>). Three levels are supported:</p><table tabindex="0"><thead><tr><th>Wildcard</th><th>Matching Rule (regex)</th><th>Description</th></tr></thead><tbody><tr><td><code>*</code></td><td><code>/[^?/]*/</code></td><td>Matches any characters within the current path segment (excluding <code>/</code> and <code>?</code>)</td></tr><tr><td><code>**</code></td><td><code>/[^?]*/</code></td><td>Matches any characters (excluding <code>?</code>), can span multiple path segments</td></tr><tr><td><code>***</code></td><td><code>/.*/</code></td><td>Matches all remaining characters (including <code>/</code> and <code>?</code>), typically used at the end of the path</td></tr></tbody></table><p><strong>Example 1: <code>*</code></strong><br> Pattern: <code>^https://example.com/path/to/a*b</code><br> ✅ Matches: <code>https://example.com/path/to/axxxb/...?query</code><br> ❌ Does not match: <code>https://example.com/path/to/a/b</code> (<code>*</code> cannot match <code>/</code>)</p><p><strong>Example 2: <code>**</code></strong><br> Pattern: <code>^https://example.com/path/to/a**b</code><br> ✅ Matches:</p><ul><li><code>https://example.com/path/to/axxxb/...?query</code></li><li><code>https://example.com/path/to/a/b</code><br> ❌ Does not match: <code>https://example.com/path/to/a/xxxx?query=b</code> (after <code>?</code> is not part of path)</li></ul><p><strong>Example 3: <code>***</code></strong><br> Pattern: <code>^https://www.example*.com:8*/path/to/a***b</code><br> ✅ Matches:</p><ul><li><code>https://example.com/path/to/axxxb/...?query</code></li><li><code>https://example.com/path/to/a/b</code></li><li><code>https://example.com/path/to/a/xxxx?query=b</code> (<code>***</code> matches <code>?</code> and beyond)</li></ul><blockquote><p><code>***</code> consumes all remaining characters including <code>?</code>. It is recommended only at the end of the path.</p></blockquote><h3 id="_3-query-parameter-wildcard" tabindex="-1">3. Query Parameter Wildcard <a class="header-anchor" href="#_3-query-parameter-wildcard" aria-label="Permalink to &quot;3. Query Parameter Wildcard&quot;">​</a></h3><p>Applies to the <strong>query string</strong> (after <code>?</code>). Two levels are supported:</p><table tabindex="0"><thead><tr><th>Wildcard</th><th>Matching Rule (regex)</th><th>Description</th></tr></thead><tbody><tr><td><code>*</code></td><td><code>/[^&amp;]*/</code></td><td>Matches any characters within a single parameter value (excluding <code>&amp;</code>)</td></tr><tr><td><code>**</code></td><td><code>/.*/</code></td><td>Matches all remaining characters (including <code>&amp;</code>), i.e., from current position to end</td></tr></tbody></table><p><strong>Example 1: <code>*</code></strong><br> Pattern: <code>^https://example.com/path/to?query=a*b</code><br> ✅ Matches: <code>https://example.com/path/to?query=ab&amp;q2=xxx</code><br> ❌ Does not match: <code>https://example.com/path/to?query=a&amp;q2=b</code> (no extra characters before <code>b</code>)</p><p><strong>Example 2: <code>**</code></strong><br> Pattern: <code>^https://example.com/path/to?query=a**b</code><br> ✅ Matches:</p><ul><li><code>https://example.com/path/to?query=axxxb&amp;q2=xxx</code></li><li><code>https://example.com/path/to?query=a&amp;q2=b</code> (<code>**</code> matches <code>&amp;q2=</code>)</li></ul><h3 id="_4-exact-match-without-protocol" tabindex="-1">4. Exact Match Without Protocol <a class="header-anchor" href="#_4-exact-match-without-protocol" aria-label="Permalink to &quot;4. Exact Match Without Protocol&quot;">​</a></h3><p>Write the domain and path directly after <code>^</code>, any protocol is allowed.</p><p><strong>Example</strong>: <code>^example*.com/path*/to</code><br> Same effect as with protocol, but matches any protocol (http, https, wss, etc.).</p><h3 id="_5-exact-matching-boundary-control" tabindex="-1">5. Exact Matching (Boundary Control) <a class="header-anchor" href="#_5-exact-matching-boundary-control" aria-label="Permalink to &quot;5. Exact Matching (Boundary Control)&quot;">​</a></h3><p>Use <code>$</code> at the end of the pattern to indicate that matching must end there (no extra characters afterwards).</p><p><strong>Example</strong>: <code>^https://*.example.com/path/*/to$</code><br> ✅ Matches: <code>https://a.example.com/path/xxx/to</code><br> ❌ Does not match: <code>https://b.example.com/path/xxx/to?query</code> (<code>$</code> disallows <code>?query</code>)</p><blockquote><p>Without <code>$</code>, the pattern allows additional <code>/</code>, <code>?</code>, etc., after the path.</p></blockquote><h3 id="usage-summary" tabindex="-1">Usage Summary <a class="header-anchor" href="#usage-summary" aria-label="Permalink to &quot;Usage Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Prefix</th><th>Wildcard Type</th><th>Supported Wildcards</th><th>Example</th></tr></thead><tbody><tr><td>Normal URL match (no wildcards)</td><td>None</td><td>—</td><td>—</td><td><code>https://example.com/path</code></td></tr><tr><td>Path/query with wildcards</td><td><code>^</code></td><td>domain, path, query</td><td><code>*</code> <code>**</code> <code>***</code></td><td><code>^https://*.example.com/path/*?a**b</code></td></tr><tr><td>Exact match (trailing boundary)</td><td><code>^</code> + <code>$</code></td><td>same as above</td><td>same as above</td><td><code>^https://example.com/path/*/to$</code></td></tr></tbody></table><blockquote><p><strong>Note</strong>: Once you use <code>^</code>, the <code>*</code> in the URL is no longer a literal character but a wildcard. To match a literal <code>*</code>, do not use <code>^</code>.</p></blockquote><h2 id="regexp" tabindex="-1">Regex Matching <a class="header-anchor" href="#regexp" aria-label="Permalink to &quot;Regex Matching {#regexp}&quot;">​</a></h2><p>In addition to the URL fragment and wildcard matching described above, Whistle provides full regular expression support.<br> The regex syntax is fully compatible with JavaScript regular expressions:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pattern/[i]</span></span></code></pre></div><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><ul><li><strong><code>pattern</code></strong>: The regular expression body</li><li><strong><code>i</code></strong> (optional): Case-insensitive matching</li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/\\.test\\./              # Matches &quot;.test.&quot;</span></span>
<span class="line"><span>/key=value/i            # Case-insensitive match for &quot;key=value&quot; or &quot;KEY=VALUE&quot;</span></span></code></pre></div><h2 id="sub-match-value-passing" tabindex="-1">Sub-match Value Passing <a class="header-anchor" href="#sub-match-value-passing" aria-label="Permalink to &quot;Sub-match Value Passing&quot;">​</a></h2><p>In Whistle rules, you can reference sub-match contents captured by wildcards or regular expressions using <code>$0</code>, <code>$1</code> … <code>$9</code>, and pass them to target operation values.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pattern protocol://$0_$1_$2_..._$9</span></span></code></pre></div><p><strong>Capture variable description</strong>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>$0</code></td><td>The entire matched content</td></tr><tr><td><code>$1</code> ~ <code>$9</code></td><td>Content captured by the 1st to 9th capturing group</td></tr></tbody></table><h3 id="wildcard-matching-value-passing" tabindex="-1">Wildcard Matching Value Passing <a class="header-anchor" href="#wildcard-matching-value-passing" aria-label="Permalink to &quot;Wildcard Matching Value Passing&quot;">​</a></h3><p>Wildcard patterns prefixed with <code>^</code> (using <code>*</code>, <code>**</code>, etc.) automatically capture matched segments in order, assigning them to <code>$1</code>, <code>$2</code>, and so on.</p><p><strong>Example</strong>:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>^http://*.example.com/v0/users/** file:///User/xxx/$1/$2</span></span></code></pre></div><ul><li>Request URL: <code>http://www.example.com/v2/users/alice/test.html?q=1</code></li><li>Matching process: <ul><li><code>$1</code> = <code>www</code> (matches the first <code>*</code>)</li><li><code>$2</code> = <code>users/alice</code> (matches the path segment captured by <code>**</code>)</li></ul></li><li>Result: Returns content of local file <code>/User/xxx/www/alice/test.html</code></li></ul><blockquote><p>Wildcard capture rules:</p><ul><li><code>*</code> captures a single path segment (no <code>/</code>)</li><li><code>**</code> captures the remaining path (may contain <code>/</code>)</li><li>They correspond to <code>$1</code>, <code>$2</code>, … from left to right.</li></ul></blockquote><h3 id="regex-matching-value-passing" tabindex="-1">Regex Matching Value Passing <a class="header-anchor" href="#regex-matching-value-passing" aria-label="Permalink to &quot;Regex Matching Value Passing&quot;">​</a></h3><p>When using a regex pattern <code>/pattern/flags</code>, the content inside capturing groups <code>( )</code> is assigned to <code>$1</code>, <code>$2</code>, … in order.</p><p><strong>Example</strong>:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/regexp\\/(user|admin)\\/(\\d+)/ reqHeaders://X-Type=$1&amp;X-ID=$2</span></span></code></pre></div><ul><li>Request URL: <code>.../regexp/admin/123</code></li><li>Capture results: <ul><li><code>$1</code> = <code>admin</code></li><li><code>$2</code> = <code>123</code></li></ul></li><li>Result: Adds request headers <code>X-Type: admin</code> and <code>X-ID: 123</code></li></ul><hr><h2 id="path-auto-splicing-rule" tabindex="-1">Path Auto-splicing Rule <a class="header-anchor" href="#path-auto-splicing-rule" aria-label="Permalink to &quot;Path Auto-splicing Rule&quot;">​</a></h2><p>When using <strong>domain matching</strong> or <strong>path matching</strong> to map to a local file/directory or remote URL, Whistle automatically appends the remaining path from the original request.</p><p><strong>Rule</strong>:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://*.example.com/path/to https://www.test.com/test</span></span>
<span class="line"><span>www.example.com file:///Usr/test</span></span></code></pre></div><p><strong>Effect</strong>:</p><table tabindex="0"><thead><tr><th>Request URL</th><th>Mapped Target</th></tr></thead><tbody><tr><td><code>https://abc.example.com/path/to/x/y/z?query</code></td><td><code>https://www.test.com/test/x/y/z?query</code></td></tr><tr><td><code>https://www.example.com/path/to/index.html?query</code></td><td>Local file <code>/Usr/test/path/to/index.html</code> (query removed)</td></tr></tbody></table><blockquote><p>Note: Query parameters <code>?query</code> are automatically ignored when mapping to local files (file system paths do not support them), but are retained when mapping to a remote URL.</p></blockquote><hr><h2 id="configuration-examples" tabindex="-1">Configuration Examples <a class="header-anchor" href="#configuration-examples" aria-label="Permalink to &quot;Configuration Examples&quot;">​</a></h2><h3 id="basic-matching" tabindex="-1">Basic Matching <a class="header-anchor" href="#basic-matching" aria-label="Permalink to &quot;Basic Matching&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Exact domain match</span></span>
<span class="line"><span>api.example.com proxy://127.0.0.1:3000</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Domain match with specific port</span></span>
<span class="line"><span>www.example.com:8080 file:///local/dev</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Path match (map to local JSON data)</span></span>
<span class="line"><span>www.example.com/api/users file://{user-data}</span></span></code></pre></div><h3 id="wildcard-matching" tabindex="-1">Wildcard Matching <a class="header-anchor" href="#wildcard-matching" aria-label="Permalink to &quot;Wildcard Matching&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Match all subdomains</span></span>
<span class="line"><span>**.example.com proxy://127.0.0.1:8080</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Match subdomains with a specific prefix</span></span>
<span class="line"><span>dev-**.example.com file:///(dev-mock)</span></span></code></pre></div><h3 id="regex-matching" tabindex="-1">Regex Matching <a class="header-anchor" href="#regex-matching" aria-label="Permalink to &quot;Regex Matching&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Match user pages with numeric ID</span></span>
<span class="line"><span>/^https?://www\\.example\\.com/user/(\\d+)/ file://(user-$1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Case-insensitive match for a specific path</span></span>
<span class="line"><span>/\\/api\\/v1\\/data/i resBody://({&quot;version&quot;:&quot;v1&quot;})</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Match static assets and set cache</span></span>
<span class="line"><span>/\\.(jpg|png|gif|css|js)$/i cache://86400</span></span></code></pre></div><h3 id="complex-matching" tabindex="-1">Complex Matching <a class="header-anchor" href="#complex-matching" aria-label="Permalink to &quot;Complex Matching&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Wildcard + path capture value passing</span></span>
<span class="line"><span>^https://**.example.com/api/*/v*/users reqHeaders://x-api-version=$3</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Handle by request method</span></span>
<span class="line"><span>www.example.com/api file://({&quot;status&quot;:&quot;ok&quot;}) includeFilter://m:GET</span></span>
<span class="line"><span>www.example.com/api file://({&quot;status&quot;:&quot;created&quot;}) includeFilter://m:POST</span></span></code></pre></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="q-the-rule-does-not-match-the-request" tabindex="-1">Q: The rule does not match the request <a class="header-anchor" href="#q-the-rule-does-not-match-the-request" aria-label="Permalink to &quot;Q: The rule does not match the request&quot;">​</a></h3><p><strong>Possible causes and solutions</strong>:</p><ol><li><p><strong>Incorrect URL format</strong><br> → Ensure the protocol (http/https/ws/wss) in the rule matches the request, or use a protocol-less pattern (<code>example.com/path</code>).</p></li><li><p><strong>Port mismatch</strong><br> → If the request uses a non-standard port, specify the port explicitly in the rule (e.g., <code>example.com:8080</code>).</p></li><li><p><strong>Wildcard or regex error</strong><br> → Use <a href="https://github.com/avwo/whistle" target="_blank" rel="noreferrer">Whistle online debugging tools</a> or local logs to verify matching.</p></li><li><p><strong>Rule priority issues</strong><br> → Place more specific rules earlier, or use <code>$</code> exact matching to increase priority.</p></li></ol><h3 id="q-regex-does-not-work" tabindex="-1">Q: Regex does not work <a class="header-anchor" href="#q-regex-does-not-work" aria-label="Permalink to &quot;Q: Regex does not work&quot;">​</a></h3><p><strong>Checklist</strong>:</p><ul><li>[ ] Does the regex start and end with <code>/</code>, e.g., <code>/pattern/</code>?</li><li>[ ] Are special characters escaped (e.g., <code>.</code> -&gt; <code>\\.</code>, <code>/</code> -&gt; <code>\\/</code>)?</li><li>[ ] Are flags (e.g., <code>i</code>) correctly added?</li><li>[ ] Does the regex match the full URL? Test in console with <code>new RegExp(&#39;pattern&#39;, &#39;flags&#39;).test(url)</code>.</li></ul><h3 id="q-sub-match-value-passing-is-incorrect" tabindex="-1">Q: Sub-match value passing is incorrect <a class="header-anchor" href="#q-sub-match-value-passing-is-incorrect" aria-label="Permalink to &quot;Q: Sub-match value passing is incorrect&quot;">​</a></h3><p><strong>Common issues</strong>:</p><ol><li><p><strong>Wrong capture group number</strong><br> → <code>$1</code> corresponds to the first <code>( )</code>, <code>$2</code> to the second, and so on. Pay attention to nested capture groups.</p></li><li><p><strong>Wildcard capture does not behave as expected</strong><br> → <code>*</code> does not match dot (<code>.</code>) or slash (<code>/</code>); <code>**</code> matches any character except <code>?</code>.<br> → Example: <code>*.example.com</code> cannot match <code>a.b.example.com</code>; use <code>**.example.com</code> instead.</p></li><li><p><strong>Regex capture groups not working as expected</strong><br> → Use <code>(?:)</code> for non-capturing groups to avoid interfering with numbering.<br> → Test with online regex tools (e.g., regex101.com) to verify captured content.</p></li></ol><h3 id="q-wrong-path-when-mapping-to-local-file" tabindex="-1">Q: Wrong path when mapping to local file <a class="header-anchor" href="#q-wrong-path-when-mapping-to-local-file" aria-label="Permalink to &quot;Q: Wrong path when mapping to local file&quot;">​</a></h3><ul><li>When using the <code>file://</code> protocol, ensure the path is absolute (e.g., <code>file:///User/xxx</code>).</li><li>Path splicing follows the auto-splicing rule: the remaining path of the request is appended to the target path.</li><li>Query parameters are automatically ignored and do not affect file reading.</li></ul><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="./rule.html">Rule Syntax Documentation</a>: Learn the complete rule syntax structure</li><li><a href="./operation.html">Operation Directive Documentation</a>: Learn how to configure operation directives</li><li><a href="./filters.html">Filter Documentation</a>: Understand how to precisely control rule activation conditions</li></ul>`,120)]))}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
